values ('directory-voya-house',
'{"id":"directory-voya-house","name":"VOYA House — فويا هاوس","category":"كافيه ومطعم","address":"كيان سيتي — PX Mall — سنتر نادي الفروسية، حسب إعلان الفرع","description":"فويا هاوس في كيان سيتي. المنيو العربي الرسمي لفرع كيان يضم قهوة ومشروبات وإفطار وبيتزا وبرجر وأطباق دجاج ولحوم وأسماك واختيارات بابا فويا. الأسعار المنشورة قبل إضافة ١٤٪ ضريبة؛ أكّد الإجمالي والتوفر مع النشاط.","source":"https://linktr.ee/voyahouse","status":"صفحة فويا الرسمية تربط المنيو العربي والموقع بفرع كيان. تاريخ سريان الأسعار غير مطبوع؛ يضاف ١٤٪ ضريبة حسب المنيو. الموقع نقطة منشورة من النشاط، وليس تحققًا من المدخل أو إتاحة الطرق والبوابات. رقم التواصل المعلن لفرع الكيان مشترك أيضًا مع فرع آخر.","checkedAt":"2026-11-04","sourceDate":null,"menuStatus":"official_published","menuCheckedAt":"2026-11-04","menuNote":"منيو عربي يربطه حساب فويا الرسمي بفرع كيان. تاريخ النشر غير معلن؛ تاريخ تعديل الملف ليس تاريخ سريان للأسعار. الأسعار قبل إضافة ١٤٪ ضريبة؛ أكد الإجمالي والتوفر قبل الطلب.","aliases":["VOYA","VOYA House","فويا","فويا هاوس","ڤويا"],"keywords":["مطعم","كافيه","بيتزا","قهوة","PX Mall","نادي الفروسية","منيو فويا"],"mapCategory":"restaurant","schemaType":"Restaurant","website":"https://linktr.ee/voyahouse","openingSource":"https://www.facebook.com/groups/239237117828530/permalink/1692146779204216/","coordinate":[31.624669,29.961482],"mapId":"directory-voya-house","precision":"published_place_point","externalMapUrl":"https://www.google.com/maps?q=29.961482,31.624669","coordinateSource":"https://linktr.ee/voyahouse","menuPublishedAt":null,"menuUrl":"https://drive.google.com/file/d/1BiuWaK1cYsPUfE8DPmk2vtGybkdn89SP/view","menuSource":"https://linktr.ee/voyahouse","menuImages":["/menus/voya/page-2.png","/menus/voya/page-4.png","/menus/voya/page-6.png"],"menuTaxIncluded":false,"menuTaxRate":14,"phone":"+201103490030","phoneSource":"https://linktr.ee/voyahouse","phoneSourceLabel":"فرع الكيان","phoneNote":"رقم تواصل منشور تحت فرع الكيان في حساب فويا الرسمي؛ الرقم نفسه معلن لفرع آخر أيضًا.","url":"/place/directory-voya-house","image":"/social/directory-voya-house.png","district":"other"}'::jsonb,
array['+201103490030'],
'[{"phone":"+201103490030","sourceUrl":"https://linktr.ee/voyahouse","sourceType":"official_business","checkedAt":"2026-11-04","sourceLabel":"فرع الكيان","note":"Official contact sheet labels this phone for Kayan; same shared business phone is also listed for another branch."}]'::jsonb)
